  on_arm do
    url "https://github.com/filoucrackeur/php-fpm-monitor/releases/download/v1.0.0/fpm-monitor-aarch64-apple-darwin"
    sha256 "8686aad0cc43bae37b821a9ec0289e7dfe07781fcc60f0df75572e7764ea3ae2"
  end

  def install
    if Hardware::CPU.arm?
      bin.install "fpm-monitor-aarch64-apple-darwin" => "fpm-monitor"
    else
      bin.install "fpm-monitor-x86_64-apple-darwin" => "fpm-monitor"
    end
  end

  test do
    assert_match "fpm-monitor", shell_output("#{bin}/fpm-monitor --help")
